        "title": "中信证券：锂价未来2–3个月有望升至25万元/吨，1–4月储能电池销量同比翻倍",
        "summary": "新浪财经5月12日转引新华财经称，中信证券研报认为非洲、江西、澳洲Greenbushes和南美锂盐供应扰动叠加储能需求超预期，锂价未来2–3个月有望上涨至25万元/吨；1–4月国内储能电池销量200.4GWh，同比+100.4%，5月国内电池排产环比+6%。",
        "body": [
          "中信证券研报公开转述称，津巴布韦锂精矿出口恢复仍有运输滞后，江西部分瓷土矿采矿证流程或带来停产风险，Greenbushes 2026财年产量指引中值下调17.5万吨矿、折合超过2万吨LCE。",
          "需求端，2026年4月中国动力电池及其他电池产量183.9GWh，1–4月产量671.2GWh、同比+51.0%；1–4月国内储能电池销量200.4GWh、同比+100.4%。",
          "库存端，据SMM，上周碳酸锂库存降至10.3万吨、冶炼厂库存1.9万吨；大东时代智库称5月国内电池排产环比+6%。该条强化MarketTrend锂盐偏多证据。"
        ],
