        "clean_html": "<figure><img src=\"https://public.solarbe.com/webupload/image/News/20260510/3e19a00d68000a2.png\" alt=\"正文图片 1\" /></figure>\n<p>近日，三晖能源乌克兰 3.75MW/15MWh 长时储能项目完成出厂前验收并装车启运。该项目用于乌克兰电网稳定、能源重建和关键基础设施供电保障。</p>\n<p>本次发货系统为 4 小时长时构网型储能解决方案，采用一体化预制舱集成设计，覆盖 PCS、储能电池簇、升压变压器、高低压开关柜、消防温控系统及 BMS/EMS 管理系统。</p>\n<p>系统具备 -30℃ 至 55℃ 宽温域运行能力，可在并网调压调频与孤网黑启动模式之间切换，适配极端气候和电网薄弱场景。</p>",
        "key_points": [
          "规模：3.75MW/15MWh。",
          "时长：4 小时长时储能。",
          "功能：构网、调压调频、孤网黑启动。",
          "场景：乌克兰电网稳定与关键负荷备用电源。"
        ],
