        "title": "储能“容量电价”开闸：全国已有 11 省明确独立储能容量电价或补偿政策",
        "summary": "碳索储能网 5 月 9 日梳理显示，截至 2026 年 5 月，全国已有 11 个省份明确独立储能容量电价或补偿政策，价格、补偿模式和考核机制差异明显。",
        "body": [
          "碳索储能网 5 月 9 日梳理，截至 2026 年 5 月，全国已有 11 个省份明确独立储能容量电价或补偿政策，覆盖西北、华北、华东、华南、华中等区域。",
          "文章指出，容量电价或补偿模式主要分为三类：煤电基准型、电量激励型和市场化复合型。不同省份在容量电价标准、净负荷高峰持续时长、调用率、非停扣减、可用率等考核机制上差异显著。",
          "净负荷高峰持续时长成为影响项目收益的关键变量。以 6 小时标准为例，2 小时储能可靠容量系数约为 0.33，4 小时储能约为 0.67，6 小时及以上储能可按 1 计算。容量价值机制正在推动储能项目从装机规模竞争转向可用容量和持续放电能力竞争。"
        ],
        "key_points": [
          "政策覆盖：已有 11 省明确独立储能容量电价或补偿政策。",
          "机制差异：煤电基准型、电量激励型、市场化复合型并存。",
          "影响：长时储能和高可用率电站更容易获得完整容量价值。"
        ],
