        "summary": "碳索储能网 5 月 9 日信息显示，山东电力市场规则修订后，新型储能电站可同时参与电能量市场和辅助服务市场。",
        "body": [
          "5 月 8 日，国家能源局山东监管办公室印发《山东电力市场规则（试行）》（2026 年 4 月修订版）。规则明确，新型储能电站被允许同时参与电能量市场和辅助服务市场。",
          "符合条件的新型经营主体可根据运营策略选择同时参与两类市场，也可按日仅参与电能量市场或仅参与辅助服务市场。参与电能量市场要求新型储能连续充放电时长不低于 2 小时，参与调频等辅助服务市场要求连续充放电时长不低于 15 分钟。",
          "山东当前辅助服务市场暂开展调频和爬坡辅助服务集中交易，调频里程价格上限为 12 元/兆瓦，下限为 0.1 元/兆瓦。"
        ],
        "key_points": [
          "储能可同时参与电能量市场和辅助服务市场。",
          "电能量市场连续充放电时长不低于 2 小时。",
          "调频辅助服务市场采用调频里程单一制价格机制。"
        ],
        "date": "05-09",
        "url": "https://cn.solarbe.com/news/20260509/50022788.html"
