        "summary": "2026年第一季度，中国新型储能市场延续高增态势，采招落地容量超170GWh，同比增长超60%。4h及以上长时储能合计占比已超50%，首次超过2h储能占比，储能市场正从调峰向能量管理升级。",
        "body": [
          "2026年第一季度，中国国内新型储能市场延续高增态势，Q1全国储能采招落地容量规模合计超170GWh（含电芯采购类项目），容量同比增长超60%。其中，3月落地容量近80GWh，为季内单月最高值。",
          "从采购结构看，集采/框采类项目规模占比约45%，中国电气装备集团、中国华电集团、国家电投、中广核等电力央企相继公布多次大型电芯、储能系统招标结果，合计采购规模超60GWh。",
          "从储能时长看，Q1 2h储能系统占比约44%，而4h及以上长时储能合计占比已超50%，标志着市场正从以调峰为主的短时储能，向以能量管理为核心的长时储能全面升级。"
        ],
        "key_points": [
          "Q1采招落地超170GWh，同比增长超60%，3月单月近80GWh",
          "4h及以上长时储能合计占比首次超过50%，结构性转变明显",
          "中国电气装备、国家电投、中广核等央企集采合计超60GWh"
        ],
