        "title": "中广核云南元江领航 100MW/200MWh 新型共享储能电站全容量并网",
        "summary": "5 月 8 日，中广核新能源云南元江领航 100MW/200MWh 新型共享储能电站实现全容量并网发电，支撑玉溪区域电网运行和新能源消纳。",
        "body": [
          "项目位于云南省玉溪市元江县，设计规模为 100MW/200MWh，并新建 1 座 110kV 升压站和 20 个 5MWh 储能单元。",
          "项目采用磷酸铁锂储能技术路线并应用构网型技术，可增强储能系统对电网的主动支撑能力，平抑风电、光伏等可再生能源出力波动。",
          "电站投运后预计每年向电网放电约 6570 万千瓦时，等效节约标煤约 1.97 万吨，减排二氧化碳约 5.91 万吨。"
        ],
        "clean_html": "<figure><img src=\"https://public.solarbe.com/webupload/image/News/20260510/3e19a00d68000aa.png\" alt=\"正文图片 1\" /></figure>\n<figure><img src=\"https://public.solarbe.com/webupload/image/News/20260510/3e19a00d68000ac.png\" alt=\"正文图片 2\" /></figure>\n<p>5 月 8 日，中广核新能源云南元江领航 100MW/200MWh 新型共享储能电站实现全容量并网发电。该项目服务云南玉溪区域电网安全稳定运行和可再生能源消纳，也是当地新型电力系统建设的重要节点。</p>\n<p>电站位于云南省玉溪市元江县，设计规模为 100MW/200MWh，新建 1 座 110kV 升压站和 20 个 5MWh 储能单元。项目采用磷酸铁锂储能技术路线，并引入构网型技术，提升储能系统主动支撑电网的能力。</p>\n<p>按照公开信息，项目投运后预计每年可向电网放电约 6570 万千瓦时，等效节约标煤约 1.97 万吨，减排二氧化碳约 5.91 万吨。</p>",
        "key_points": [
          "规模：100MW/200MWh。",
          "配置：1 座 110kV 升压站，20 个 5MWh 储能单元。",
          "技术路线：磷酸铁锂储能，应用构网型技术。",
          "预期放电量：约 6570 万千瓦时/年。"
        ],
