        "title": "昆明安宁 350MW 压缩空气储能示范项目首罐混凝土浇筑",
        "summary": "中国能建云南院总承包建设的昆明安宁 350MW 压缩空气储能示范项目完成主厂房基础首罐混凝土浇筑，地上工程进入主体结构施工阶段。",
        "body": [
          "5 月 8 日，昆明安宁 350MW 压缩空气储能示范项目主厂房基础完成第一罐混凝土浇筑，项目建设节奏进入主体结构施工阶段。",
          "该项目是西南地区高原盐穴压缩空气储能示范项目，依托昆明盐矿退役盐穴建设地下储气库，采用非补燃压缩空气储能技术。",
          "项目建成后将接入昆明主电网，承担调峰、调频、系统备用、黑启动等任务，是云南长时储能和新型电力系统建设的重要工程。"
        ],
        "clean_html": "<figure><img src=\"https://public.solarbe.com/webupload/image/News/20260510/3e19a00d68000a6.png\" alt=\"正文图片 1\" /></figure>\n<figure><img src=\"https://public.solarbe.com/webupload/image/News/20260510/3e19a00d68000a8.png\" alt=\"正文图片 2\" /></figure>\n<p>5 月 8 日，中国能建中电工程云南院总承包建设的昆明安宁 350MW 压缩空气储能示范项目完成主厂房基础首罐混凝土浇筑。该节点意味着项目地上工程正式转入主体结构施工阶段。</p>\n<p>项目采用非补燃压缩空气储能技术，依托昆明盐矿退役盐穴建设地下储气库，实现低谷蓄能、高峰释能。</p>\n<p>公开信息显示，项目建成后将接入昆明主电网，承担调峰、调频、系统备用、黑启动等任务，对云南长时储能示范和新能源消纳具有标志意义。</p>",
