          "资料显示，赣州市虔宁储能有限公司成立于2025年9月，法定代表人为缪晗，注册资本为4000万元，位于江西省赣州市宁都县，由赣州市国投新能源发展有限公司和宁都县登峰工业投资有限责任公司分别持股51%和49%。"
