        "clean_html": "<p>远东智慧能源股份有限公司公告披露，2026年4月份公司子公司中标/签约千万元以上合同订单合计263333.28万元，约合26.33亿元。</p>\n<p>储能相关订单是本次公告的重点之一：远东储能技术有限公司获得欧洲储能系统合同约2.3997亿元，国内储能系统合同包括约1.8310亿元、1.3166亿元和5372.50万元，合计超过6亿元。</p>\n<p>该公告为上市公司订单口径，可作为储能系统交付、LFP电芯需求和电解液链条情绪的补充证据；合同履行仍以公司后续定期报告和项目交付情况为准。</p>",
